package com.infomaniak.drive.data.cache.copyreader

/** Closed persisted-field whitelist for APP3, DRIVES4 and File20; no stored values. */
internal object TransitionSchema {
    data class Backlink(val table: String, val field: String)
    data class Table(val primaryKey: String?, val fields: Map<String, String>, val computed: Map<String, Backlink>)

    private fun table(primary: String?, computed: String, vararg definitions: String): Table = Table(
        primary, definitions.flatMap { it.split(" ") }.associate { definition ->
            definition.substringBefore(":") to definition.substringAfter(":")
        }, computed.split(" ").filter(String::isNotEmpty).associate { definition ->
            val parts = definition.split(':')
            CopyInputGuard.require(parts.size == 3)
            parts[0] to Backlink(parts[1], parts[2])
        },
    )

    val modules = mapOf(
        "APP" to mapOf(
            "AppSettings" to table(null, "",
                "_appSecurityEnabled:BOOLEAN _currentDriveId:INTEGER _currentUserId:INTEGER",
                "_onlyWifiSyncOffline:BOOLEAN",
            ),
        ),
        "DRIVES" to mapOf(
            "Category" to table(null, "",
                "id:INTEGER color:STRING createdAt:DATE isPredefined:BOOLEAN name:STRING userUsageCount:INTEGER",
            ),
            "CategoryRights" to table(null, "",
                "canCreate:BOOLEAN canDelete:BOOLEAN canEdit:BOOLEAN canPutOnFile:BOOLEAN canReadOnFile:BOOLEAN",
            ),
            "Drive" to table("objectId", "",
                "objectId:STRING isOrganisationAdmin:BOOLEAN _rights:OBJECT:DriveRights name:STRING",
                "_preferences:OBJECT:DrivePreferences _role:STRING _capabilities:OBJECT:DriveCapabilities",
                "_quotas:OBJECT:DriveQuotas sharedWithMe:BOOLEAN userId:INTEGER",
                "_categoryRights:OBJECT:CategoryRights accountId:INTEGER _driveAccount:OBJECT:DriveAccount",
                "createdAt:INTEGER updatedAt:INTEGER usedSize:INTEGER id:INTEGER maintenance:BOOLEAN",
                "maintenanceReason:STRING maintenanceTypes:LIST:MaintenanceType pack:OBJECT:DrivePack",
                "size:INTEGER version:STRING _users:OBJECT:DriveUsersCategories",
                "_teams:OBJECT:DriveTeamsCategories categories:LIST:Category",
            ),
            "DriveAccount" to table(null, "",
                "id:INTEGER name:STRING _legalEntityType:STRING",
            ),
            "DriveCapabilities" to table(null, "",
                "useVersioning:BOOLEAN useUploadCompression:BOOLEAN useTeamSpace:BOOLEAN canAddUser:BOOLEAN",
                "canSeeStats:BOOLEAN canUpgradeToKsuite:BOOLEAN canRewind:BOOLEAN",
            ),
            "DrivePack" to table(null, "",
                "id:INTEGER name:STRING _capabilities:OBJECT:DrivePackCapabilities",
            ),
            "DrivePackCapabilities" to table(null, "",
                "useVault:BOOLEAN useManageRight:BOOLEAN canSetTrashDuration:BOOLEAN useDropbox:BOOLEAN",
                "canRewind:BOOLEAN useFolderCustomColor:BOOLEAN canAccessDashboard:BOOLEAN",
                "canSetSharelinkPassword:BOOLEAN canSetSharelinkExpiration:BOOLEAN",
                "canSetSharelinkCustomUrl:BOOLEAN",
            ),
            "DrivePreferences" to table(null, "",
                "_color:STRING hide:BOOLEAN",
            ),
            "DriveQuota" to table(null, "",
                "current:INTEGER max:INTEGER",
            ),
            "DriveQuotas" to table(null, "",
                "dropbox:OBJECT:DriveQuota sharedLink:OBJECT:DriveQuota",
            ),
            "DriveRights" to table(null, "",
                "technical:BOOLEAN",
            ),
            "DriveTeamsCategories" to table(null, "",
                "account:INTEGER_LIST drive:INTEGER_LIST",
            ),
            "DriveUser" to table("id", "",
                "id:INTEGER displayName:STRING avatar:STRING email:STRING _role:STRING right:STRING",
            ),
            "DriveUsersCategories" to table(null, "",
                "account:INTEGER_LIST drive:INTEGER_LIST internal:INTEGER_LIST external:INTEGER_LIST",
            ),
            "MaintenanceType" to table(null, "",
                "_code:STRING",
            ),
            "Team" to table("id", "",
                "id:INTEGER name:STRING right:STRING color:INTEGER status:STRING users:INTEGER_LIST",
                "details:LIST:TeamDetails",
            ),
            "TeamDetails" to table(null, "",
                "driveId:INTEGER usersCount:INTEGER",
            ),
        ),
        "FILES" to mapOf(
            "DropBox" to table(null, "",
                "id:INTEGER name:STRING capabilities:OBJECT:DropBoxCapabilities url:STRING uuid:STRING",
                "createdAt:DATE createdBy:INTEGER lastUploadedAt:INTEGER collaborativeUsersCount:INTEGER",
                "updatedAt:DATE",
            ),
            "DropBoxCapabilities" to table(null, "",
                "hasPassword:BOOLEAN hasNotification:BOOLEAN hasValidity:BOOLEAN hasSizeLimit:BOOLEAN",
                "validity:OBJECT:DropBoxValidity size:OBJECT:DropBoxSize",
            ),
            "DropBoxSize" to table(null, "",
                "limit:INTEGER remaining:INTEGER",
            ),
            "DropBoxValidity" to table(null, "",
                "date:DATE hasExpired:BOOLEAN",
            ),
            "File" to table("uid", "localParent:File:children",
                "uid:STRING id:INTEGER parentId:INTEGER driveId:INTEGER name:STRING sortedName:STRING",
                "path:STRING type:STRING status:STRING visibility:STRING createdBy:INTEGER createdAt:INTEGER",
                "addedAt:INTEGER lastModifiedAt:INTEGER deletedBy:INTEGER deletedAt:INTEGER users:INTEGER_LIST",
                "isFavorite:BOOLEAN shareLink:OBJECT:ShareLink rights:OBJECT:Rights",
                "categories:LIST:FileCategory cursor:STRING color:STRING dropbox:OBJECT:DropBox",
                "externalImport:OBJECT:FileExternalImport size:INTEGER supportedBy:STRING_LIST",
                "extensionType:STRING version:OBJECT:FileVersion conversion:OBJECT:FileConversion",
                "revisedAt:INTEGER updatedAt:INTEGER children:LIST:File isComplete:BOOLEAN",
                "isDirectlyPinned:BOOLEAN isFromUploads:BOOLEAN isMarkedAsOffline:BOOLEAN isOffline:BOOLEAN",
                "offlineBasisModifiedAt:INTEGER offlineBasisSize:INTEGER offlineContentDigest:STRING",
                "offlineOwnedByRoot:BOOLEAN offlineNeedsAttention:BOOLEAN offlinePublishedPath:STRING",
                "responseAt:INTEGER serverContentHash:STRING versionCode:INTEGER lastActionAt:INTEGER",
            ),
            "FileActivity" to table("id", "",
                "id:INTEGER action:STRING createdAt:DATE file:OBJECT:File fileId:INTEGER newPath:STRING",
                "oldPath:STRING userId:INTEGER",
            ),
            "FileCategory" to table(null, "",
                "categoryId:INTEGER userValidation:STRING isGeneratedByAI:BOOLEAN userId:INTEGER addedAt:DATE",
            ),
            "FileConversion" to table(null, "",
                "whenDownload:BOOLEAN downloadExtensions:STRING_LIST whenOnlyoffice:BOOLEAN",
                "onlyofficeExtension:STRING",
            ),
            "FileExternalImport" to table(null, "",
                "id:INTEGER application:STRING accountName:STRING status:STRING path:STRING directoryId:INTEGER",
                "hasSharedFiles:STRING createdAt:INTEGER updatedAt:INTEGER countSuccessFiles:INTEGER",
                "countFailedFiles:INTEGER",
            ),
            "FileVersion" to table(null, "",
                "isMultiple:BOOLEAN number:INTEGER totalSize:INTEGER",
            ),
            "OfflineFolderRoot" to table("uid", "",
                "uid:STRING folderId:INTEGER driveId:INTEGER userId:INTEGER markedAt:DATE",
            ),
            "Rights" to table(null, "",
                "canBecomeDropbox:BOOLEAN canBecomeShareLink:BOOLEAN canCreateDirectory:BOOLEAN",
                "canCreateFile:BOOLEAN canDelete:BOOLEAN canLeave:BOOLEAN canMove:BOOLEAN canMoveInto:BOOLEAN",
                "canRead:BOOLEAN canRename:BOOLEAN canShare:BOOLEAN canShow:BOOLEAN canUpload:BOOLEAN",
                "canUseFavorite:BOOLEAN canUseTeam:BOOLEAN canWrite:BOOLEAN colorable:BOOLEAN right:STRING",
            ),
            "ShareLink" to table(null, "",
                "url:STRING fileId:INTEGER _right:STRING validUntil:DATE",
                "capabilities:OBJECT:ShareLinkCapabilities accessBlocked:BOOLEAN",
            ),
            "ShareLinkCapabilities" to table(null, "",
                "canEdit:BOOLEAN canSeeStats:BOOLEAN canDownload:BOOLEAN",
            ),
        ),
    )
}
